window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-22691\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοίησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1906 na letra κ · nº geral 22691</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">presunção; orgulho. 〈κατά, οἴομαι〉</p></section></article>\n<article id=\"entry-dgp-22692\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1907 na letra κ · nº geral 22692</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 habitar como colono; estabelecer-se em, ac. 2 governar; administrar 3 fixar residência em; estabelecer-se em; habitar 4 viver em: κατ. ἐν μοναρχίᾳ isócr. viver numa monarquia 5 estar situado em, ἐν e dat. ♦ méd. 6 estabelecer-se em 7 perf. e m.-q.-perf. habitar 8 ocupar como colono (uma cidade) ♦ pas. ser habitado.</p></section></article>\n<article id=\"entry-dgp-22693\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοίκησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1908 na letra κ · nº geral 22693</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de estabelecer-se em uma residência 2 fundação ou povoamento de uma colônia 3 habitação; residência 4 região habitada. 〈κατοικέω〉</p></section></article>\n<article id=\"entry-dgp-22694\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικητήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1909 na letra κ · nº geral 22694</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. residência; moradia. 〈κα­τοικέω〉</p></section></article>\n<article id=\"entry-dgp-22695\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1910 na letra κ · nº geral 22695</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de estabelecer-se como morador, de residir 2 habitação 3 casa de campo 4 fundação de colônia 5 colônia. 〈κατά, οἰκία〉</p></section></article>\n<article id=\"entry-dgp-22696\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικίδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1911 na letra κ · nº geral 22696</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que vive na casa; doméstico 2 que vive em casa; sedentário 3 que pode ser preparado em casa (remédio); caseiro. 〈κατά, οἶκος〉</p></section></article>\n<article id=\"entry-dgp-22697\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1912 na letra κ · nº geral 22697</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κατοικίσω, át. κατοικιῶ, aor. κατῴκισα, perf. κατῴκικα; pas. aor. κατῳκίσθην, perf. κατῴκισμαι) 1 conduzir ou estabelecer alguém ou algo, ac., em (um local), dat. ou εἰς e ac.: κατ. τινὰς ἐς Μέμφιν her. estabelecer pessoas em Mênfis, ψυχὴν ἐν τάφῳ κατ. sóf. colocar alguém ainda vivo numa sepultura, κατοικίσαι τὴν πόλιν εἰς τοιοῦτον τόπον plat. instalar a cidade em tal lugar 2 depositar; incutir; infundir: τυφλὰς ἐν αὐτοῖς ἐλπίδας κατῴκισα ésql. infundi neles cegas esperanças 3 colonizar; povoar (cidade) 4 reconduzir à pátria; repatriar (um exilado) ♦ méd. (aor. κατῳκισάμην) 5 estabelecer-se em, εἰς e ac. ou ἐν e dat. ♦ pas. 6 ter vindo estabelecer-se em, εἰς e ac. 7 ser estabelecido em; habitar; morar ἐν e dat. 〈κατά, οἰκίζω〉</p></section></article>\n<article id=\"entry-dgp-22698\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοίκισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1913 na letra κ · nº geral 22698</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fundação ou povoamento de colônia. 〈κατοικίζω〉</p></section></article>\n<article id=\"entry-dgp-22699\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1914 na letra κ · nº geral 22699</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κατοίκισις.</p></section></article>\n<article id=\"entry-dgp-22700\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικοδομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1915 na letra κ · nº geral 22700</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 edificar; construir 2 gastar em construções 3 encerrar numa casa; seqüestrar. 〈κατά, οἰκο­δομέω〉</p></section></article>\n<article id=\"entry-dgp-22701\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικονομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1916 na letra κ · nº geral 22701</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gastar com prudência; administrar bem.</p></section></article>\n<article id=\"entry-dgp-22702\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάτοικος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1917 na letra κ · nº geral 22702</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitante. 〈κατά, οἶκος〉</p></section></article>\n<article id=\"entry-dgp-22703\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικοφθορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1918 na letra κ · nº geral 22703</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arruinar completamente.</p></section></article>\n<article id=\"entry-dgp-22704\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικτείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1919 na letra κ · nº geral 22704</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sentir pena de, ac. 2 excitar a piedade de, ac.</p></section></article>\n<article id=\"entry-dgp-22705\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικτίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1920 na letra κ · nº geral 22705</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κατοικτίσω, át. κατοικτιῶ) 1 ter compaixão de, ac. 2 excitar a compaixão; fazer sentir pena; comover ♦ méd. (fut. κατοικτιοῦμαι) 3 apiedar-se de 4 lamentar-se.</p></section></article>\n<article id=\"entry-dgp-22706\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικτίρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1921 na letra κ · nº geral 22706</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κατοικτείρω.</p></section></article>\n<article id=\"entry-dgp-22707\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοίκτισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1922 na letra κ · nº geral 22707</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">piedade; compaixão. 〈κατοικίζω〉</p></section></article>\n<article id=\"entry-dgp-22708\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοίσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1923 na letra κ · nº geral 22708</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. καταφέρω.</p></section></article>\n<article id=\"entry-dgp-22709\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοκνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1924 na letra κ · nº geral 22709</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 temer; hesitar em, inf. 2 descuidar por medo.</p></section></article>\n<article id=\"entry-dgp-22710\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατολιγωρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1925 na letra κ · nº geral 22710</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 negligenciar inteiramente, gen. 2 ser negligente em, ἐν e dat.</p></section></article>\n<article id=\"entry-dgp-22711\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατολολύζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1926 na letra κ · nº geral 22711</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dar um grito de triunfo, de júbilo por algo, gen.</p></section></article>\n<article id=\"entry-dgp-22712\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατολοφύρομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1927 na letra κ · nº geral 22712</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lamentar-se sobre, ac.</p></section></article>\n<article id=\"entry-dgp-22713\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατόμνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1928 na letra κ · nº geral 22713</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κατομοῦμαι, aor. κατώμοσα, perf. κατομώμοκα) at. e méd. 1 garantir por juramento; jurar algo, ac. ou inf., a alguém, dat.; κατ. ὅρκον prestar juramento 2 tomar como testemunha com juramento; jurar por alguém ou algo, ac. ♦ méd. 3 fazer uma acusação sob juramento contra alguém, dat.</p></section></article>\n<article id=\"entry-dgp-22714\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατόνομαι (-οσαι, -οται,</h1><div class=\"entry-meta\"><span>DGP · ordem 1929 na letra κ · nº geral 22714</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. jôn. sem aum. κατονόμην) recriminar; desprezar; humilhar.</p></section></article>\n<article id=\"entry-dgp-22715\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατόπιν</h1><div class=\"entry-meta\"><span>DGP · ordem 1930 na letra κ · nº geral 22715</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 (lugar) atrás de, gen. 2 (tempo) em seguida; depois de, gen.</p></section></article>\n<article id=\"entry-dgp-22716\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατόπισθεν,</h1><div class=\"entry-meta\"><span>DGP · ordem 1931 na letra κ · nº geral 22716</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. κατόπισθε adv. 1 (lugar) atrás de, gen.; para trás: ἁ Ἀρετὰ κατ. θνατοῖς ἀμελεῖται eur. a Virtude é negligenciada pelos mortais, κατ. λιπέσθαι hom. ser deixado para trás, ser abandonado 2 (tempo) depois; em seguida. 〈κατά, ὄπισθεν〉</p></section></article>\n<article id=\"entry-dgp-22717\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοπτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1932 na letra κ · nº geral 22717</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">assar; tostar.</p></section></article>\n<article id=\"entry-dgp-22718\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοπτεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1933 na letra κ · nº geral 22718</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 examinar; observar 2 visitar; explorar uma região 3 reconhecer.</p></section></article>\n<article id=\"entry-dgp-22719\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοπτήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1934 na letra κ · nº geral 22719</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espião 2 Medic. sonda. 〈κατοπτεύω〉</p></section></article>\n<article id=\"entry-dgp-22720\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατόπτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1935 na letra κ · nº geral 22720</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquele que observa do alto, que contempla, gen.; aquele que tudo vê, epít. de Zeus 2 vigia; espião 3 testemunha ocular. 〈κατά, ὁράω〉</p></section></article>\n<article id=\"entry-dgp-22721\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάτοπτος1, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1936 na letra κ · nº geral 22721</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que vigia gen.; vigilante 2 visível. 〈καθοράω〉</p></section></article>\n<article id=\"entry-dgp-22722\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάτοπτος2, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1937 na letra κ · nº geral 22722</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">assado; tostado. 〈κατοπτάω〉</p></section></article>\n<article id=\"entry-dgp-22723\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοπτρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1938 na letra κ · nº geral 22723</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mostrar como em um espelho, ac. 2 olhar como em um espelho, ac. ♦ méd. 3 mirar-se; refletir-se. 〈κάτοπτρον〉</p></section></article>\n<article id=\"entry-dgp-22724\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοπτρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1939 na letra κ · nº geral 22724</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que concerne aos espelhos; de espelho ♦ ἡ κατοπτρική 2 ciência da reflexão da luz ♦ τὰ κατοπτρικά 3 imagens refletidas. 〈κάτοπτρον〉</p></section></article>\n<article id=\"entry-dgp-22725\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοπτρικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1940 na letra κ · nº geral 22725</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. por reflexo.</p></section></article>\n<article id=\"entry-dgp-22726\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοπτροειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1941 na letra κ · nº geral 22726</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">semelhante a um espelho. 〈κά­τοπτρον, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-22727\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάτοπτρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1942 na letra κ · nº geral 22727</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espelho 2 imagem. 〈καθοράω〉</p></section></article>\n<article id=\"entry-dgp-22728\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοράω</h1><div class=\"entry-meta\"><span>DGP · ordem 1943 na letra κ · nº geral 22728</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = καθοράω.</p></section></article>\n<article id=\"entry-dgp-22729\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοργιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1944 na letra κ · nº geral 22729</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">iniciar nos mistérios orgiásticos.</p></section></article>\n<article id=\"entry-dgp-22730\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατορθόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1945 na letra κ · nº geral 22730</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. κατώρθωσα, perf. κατώρθωκα) 1 manter ereto ou endireitar (o corpo) 2 recolocar no lugar; endireitar (osso) 3 infundir confiança em alguém, ac.; encorajar; fortalecer 4 dirigir convenientemente; conduzir satisfatoriamente (um trabalho) 5 ter êxito; prosperar em algo, περί e gen. ou ac., ἐν e dat.; τὸ κατορθοῦν dem. o sucesso, o êxito, a felicidade.</p></section></article>\n<article id=\"entry-dgp-22731\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατόρθωμα, ατος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1946 na letra κ · nº geral 22731</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 êxito; triunfo 2 ação correta; ação virtuosa. 〈κατορθόω〉</p></section></article>\n<article id=\"entry-dgp-22732\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατόρθωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1947 na letra κ · nº geral 22732</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de endireitar, de recolocar (osso); ajuste 2 correção; melhoramento; reforma (da constituição) 3 boa direção; firmeza 4 sucesso; êxito 5 conduta reta, virtuosa, para os estóicos. 〈κατορθόω〉</p></section></article>\n<article id=\"entry-dgp-22733\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατορρωδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1948 na letra κ · nº geral 22733</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arrepiar-se de medo; tremer diante de, ac.</p></section></article>\n<article id=\"entry-dgp-22734\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατορύσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1949 na letra κ · nº geral 22734</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ύττω (fut. κατορύξω, aor. κατώρυξα) 1 enterrar; sepultar 2 arruinar completamente.</p></section></article>\n<article id=\"entry-dgp-22735\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατορχέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1950 na letra κ · nº geral 22735</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 encantar alguém, ac., com uma dança 2 dançar por zombaria diante de, gen. ou ac.; insultar; zombar.</p></section></article>\n<article id=\"entry-dgp-22736\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατότι</h1><div class=\"entry-meta\"><span>DGP · ordem 1951 na letra κ · nº geral 22736</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = καθότι.</p></section></article>\n<article id=\"entry-dgp-22737\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατουρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1952 na letra κ · nº geral 22737</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 impelir com a ajuda de um vento favorável; fazer abordar 2 ter sucesso; realizar-se.</p></section></article>\n<article id=\"entry-dgp-22738\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοφρυόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1953 na letra κ · nº geral 22738</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. perf. κατωφρυωμένος) 1 levantar as sobrancelhas; ser orgulhoso, arrogante 2 desdenhar de alguém, ac. 3 ter sobrancelhas espessas.</p></section></article>\n<article id=\"entry-dgp-22739\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοχή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1954 na letra κ · nº geral 22739</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 retenção, gen. 2 pl. impedimentos; obstáculos 3 freio de máquina 4 posse: κατ. λαβεῖν τινος filod. tomar posse de algo 5 possessão divina; inspiração; delírio 6 Medic. espécie de catalepsia 7 resistência; durabilidade de um material. 〈κατέχω〉</p></section></article>\n<article id=\"entry-dgp-22740\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατόχιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1955 na letra κ · nº geral 22740</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de que se tem a posse; que tem dono 2 dominado por uma divindade; possuído. 〈κάτοχος〉</p></section></article>\n<article id=\"entry-dgp-22741\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάτοχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1956 na letra κ · nº geral 22741</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que segura com firmeza (laço) 2 que retém bem; que tem boa memória 3 que prende; sedutor; cativante 4 retido com firmeza por algo, dat. 5 submisso a alguém, dat. 6 possuído; inspirado por um deus, ἐκ e gen. 7 Medic. vítima de catalepsia 8 seguro; firme; sólido (bem, propriedade) ♦ ἡ κάτοχος 9 Medic. espécie de epilepsia. 〈κατέχω〉</p></section></article>\n<article id=\"entry-dgp-22742\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατόχως</h1><div class=\"entry-meta\"><span>DGP · ordem 1957 na letra κ · nº geral 22742</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com tenacidade 2 com memória fidedigna 3 sob possessão ou inspiração divina 4 Medic. como em estado de possessão ou sob efeito de catalepsia; furiosamente.</p></section></article>\n<article id=\"entry-dgp-22743\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατόψιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1958 na letra κ · nº geral 22743</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que está na vista; visível 2 que está em face de, gen. 〈καθοράω〉</p></section></article>\n<article id=\"entry-dgp-22744\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατόψομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1959 na letra κ · nº geral 22744</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. καθοράω.</p></section></article>\n<article id=\"entry-dgp-22745\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοψοφαγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1960 na letra κ · nº geral 22745</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(perf. κατωψοφάγηκα, m.-q.-perf. pas. κατωψοφαγήμην) 1 alimentar-se regaladamente; comer com avidez 2 despender em pândega.</p></section></article>\n<article id=\"entry-dgp-22746\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατρεύς, έως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1961 na letra κ · nº geral 22746</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espécie de pavão da Índia.</p></section></article>\n<article id=\"entry-dgp-22747\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάτροπτον</h1><div class=\"entry-meta\"><span>DGP · ordem 1962 na letra κ · nº geral 22747</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = κάτοπτρον.</p></section></article>\n<article id=\"entry-dgp-22748\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κὰτ τάδε</h1><div class=\"entry-meta\"><span>DGP · ordem 1963 na letra κ · nº geral 22748</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = κατὰ τάδε deste modo.</p></section></article>\n<article id=\"entry-dgp-22749\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάττυμα, καττύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1964 na letra κ · nº geral 22749</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = κάσσυμα, κασσύω.</p></section></article>\n<article id=\"entry-dgp-22750\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατύπερθε, κατυπέρτερος</h1><div class=\"entry-meta\"><span>DGP · ordem 1965 na letra κ · nº geral 22750</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = καθύπερθε, καθυπέρ­τερος.</p></section></article>\n<article id=\"entry-dgp-22751\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατυπνόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1966 na letra κ · nº geral 22751</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = καθυπνόω.</p></section></article>\n<article id=\"entry-dgp-22752\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἄτυφε</h1><div class=\"entry-meta\"><span>DGP · ordem 1967 na letra κ · nº geral 22752</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de καὶ ἔτυφε.</p></section></article>\n<article id=\"entry-dgp-22753\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἄτυχον</h1><div class=\"entry-meta\"><span>DGP · ordem 1968 na letra κ · nº geral 22753</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de καὶ ἔτυχον.</p></section></article>\n<article id=\"entry-dgp-22754\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1969 na letra κ · nº geral 22754</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. (comp. κατωτέρω; superl. κατωτάτω) 1 (lugar) de cima para baixo: κ. ἕλκειν hom. puxar para baixo, κ. ὁράω hom. olhar para baixo, abaixar o olhar, κ. χωρεῖν ésql. descer, ἄνω καὶ κάτω e ἄνω κάτω át. de cima para baixo e de baixo para cima, i.e., em todos os sentidos, περιπατεῖν ἄνω κάτω ar. andar para cima e para baixo; com κατά, ἐρρίπτεον ἑωυτοὺς κατὰ τοῦ τείχεος κάτω her. [os atenienses] se jogaram muralha abaixo 2 (lugar) sob a terra; nos infernos: οἱ κάτω θεοί sóf. os deuses infernais 3 (lugar) no litoral (op. a no interior): κ. οἰκεῖν tuc. habitar no litoral 4 (lugar) em rel. à pista de corrida, do ponto de partida (op. ao ponto de chegada) 5 (tempo) em seguida; posteriormente: οἱ κ. χρόνοι plut. os tempos subseqüentes ♦ prep. 6 (lugar) do alto de, gen. ou κατά e gen. 7 (tempo) na seqüência de: κ. τοῦ χρόνου el. posteriormente ♦ οἱ κάτω 8 os habitantes dos infernos; os mortos 9 os moradores do litoral 10 os vindouros; os pósteros, op. a οἱ πάλαι ♦ τὰ κάτω 11 o litoral.</p></section></article>\n<article id=\"entry-dgp-22755\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατώβλεπον, οντος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1970 na letra κ · nº geral 22755</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">catóblepa, espécie de antílope gigante da África. 〈κάτω, βλέπω〉</p></section></article>\n<article id=\"entry-dgp-22756\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάτωθε</h1><div class=\"entry-meta\"><span>DGP · ordem 1971 na letra κ · nº geral 22756</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e κάτωθεν adv. 1 (lugar) debaixo: οἱ κάτ. θεοί sóf. os deuses infernais, ἐκ τῆς γῆς κάτ. plat. de sob a terra 2 (tempo) em seguida; posteriormente ♦ τὰ κάτωθεν 3 alicerces de um edifício.</p></section></article>\n<article id=\"entry-dgp-22757\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατωμάδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1972 na letra κ · nº geral 22757</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do alto do ombro: κατ. δίσκος hom. disco lançado do alto do ombro 2 pendurado no ombro. 〈κατά, ὦμος〉</p></section></article>\n<article id=\"entry-dgp-22758\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατωμαδόν</h1><div class=\"entry-meta\"><span>DGP · ordem 1973 na letra κ · nº geral 22758</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com um golpe no ombro 2 sobre os ombros. 〈κατά, ὦμος〉</p></section></article>\n<article id=\"entry-dgp-22759\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατωμοσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1974 na letra κ · nº geral 22759</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">testemunho prestado sob juramento contra alguém. 〈κατόμνυμι〉</p></section></article>\n<article id=\"entry-dgp-22760\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατώρα</h1><div class=\"entry-meta\"><span>DGP · ordem 1975 na letra κ · nº geral 22760</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. jôn. de καθοράω.</p></section></article>\n<article id=\"entry-dgp-22761\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατώρυξ, υκος</h1><div class=\"entry-meta\"><span>DGP · ordem 1976 na letra κ · nº geral 22761</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 enfiado ou fincado na terra (pedra) 2 situado sob a terra; subterrâneo ♦ ἡ κατώρυξ 3 caverna 4 depósito subterrâneo. 〈κατορύσσω〉</p></section></article>\n<article id=\"entry-dgp-22762\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατώτατος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1977 na letra κ · nº geral 22762</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muito baixo; o mais baixo ♦ κατώτατα adv. 2 no ponto mais baixo. 〈κάτω〉</p></section></article>\n<article id=\"entry-dgp-22763\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατωτάτω, κατωτέρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1978 na letra κ · nº geral 22763</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κάτω.</p></section></article>\n<article id=\"entry-dgp-22764\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατώτερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1979 na letra κ · nº geral 22764</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mais abaixo ou mais embaixo 2 mais jovem; posterior. 〈κάτω〉</p></section></article>\n<article id=\"entry-dgp-22765\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατωχριάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1980 na letra κ · nº geral 22765</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tornar pálido.</p></section></article>\n<article id=\"entry-dgp-22766\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καῦθις</h1><div class=\"entry-meta\"><span>DGP · ordem 1981 na letra κ · nº geral 22766</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de καὶ αὖθις.</p></section></article>\n<article id=\"entry-dgp-22767\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καυκάσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1982 na letra κ · nº geral 22767</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">do Cáucaso. 〈Καύκασος〉</p></section></article>\n<article id=\"entry-dgp-22768\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καύκασις, ιος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1983 na letra κ · nº geral 22768</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">a cadeia do Cáucaso. 〈Καύκασος〉</p></section></article>\n<article id=\"entry-dgp-22769\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καύκασος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1984 na letra κ · nº geral 22769</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Cáucaso, cadeia de montanhas entre o Ponto Euxino e o Mar Cáspio.</p></section></article>\n<article id=\"entry-dgp-22770\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καύλινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1985 na letra κ · nº geral 22770</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito com uma haste. 〈καυλός〉</p></section></article>\n<article id=\"entry-dgp-22771\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καυλομύκητες, ων (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1986 na letra κ · nº geral 22771</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Cogumelos-com-hastes, povo imaginário. 〈καυλός, μύκης〉</p></section></article>\n<article id=\"entry-dgp-22772\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυλός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1987 na letra κ · nº geral 22772</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caule; talo de planta 2 haste da lança 3 empunhadura; cabo da espada 4 raque da pena das aves 5 Anat. colo da bexiga 6 Anat. membro viril.</p></section></article>\n<article id=\"entry-dgp-22773\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καῦμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1988 na letra κ · nº geral 22773</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 calor ardente (do sol) 2 calor da febre; febre ardente 3 amor ardente; ardor; paixão 4 cicatriz de queimadura 5 brazas de sacrifício. 〈καίω〉</p></section></article>\n<article id=\"entry-dgp-22774\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυματίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1989 na letra κ · nº geral 22774</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 queimar; consumir pelo calor ♦ pas. 2 arder de febre. 〈καῦμα〉</p></section></article>\n<article id=\"entry-dgp-22775\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυματόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1990 na letra κ · nº geral 22775</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">καυματίζω.</p></section></article>\n<article id=\"entry-dgp-22776\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καυνικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1991 na letra κ · nº geral 22776</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Caunos. 〈Καῦνος〉</p></section></article>\n<article id=\"entry-dgp-22777\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καύνιος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1992 na letra κ · nº geral 22777</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 concernente a Cauno: Κ. ἔρως artt. amor de Cauno, i.e., amor infeliz ♦ οἱ Καύνιοι 2 habitantes de Cauno. 〈Καῦνος〉</p></section></article>\n<article id=\"entry-dgp-22778\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καῦνος, ου (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 1993 na letra κ · nº geral 22778</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἡ) 1 (fem.) Cauno, n. de cidade da Cária 2 (masc.) Cauno, n. do milesiano que, para fugir do amor que Bíblis, sua irmã gêmea, sentia por ele, exilou-se na Cária, onde fundou a cidade de Cauno.</p></section></article>\n<article id=\"entry-dgp-22779\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1994 na letra κ · nº geral 22779</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">chapéu de abas largas, usado pelos macedônios para proteção contra o sol. 〈καίω〉</p></section></article>\n<article id=\"entry-dgp-22780\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καύσιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1995 na letra κ · nº geral 22780</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">combustível. 〈καίω〉</p></section></article>\n<article id=\"entry-dgp-22781\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καῦσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1996 na letra κ · nº geral 22781</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 queimadura; abrasamento 2 calor cáustico 3 Medic. cauterização 4 fusão (de metal).</p></section></article>\n<article id=\"entry-dgp-22782\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καῦσος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1997 na letra κ · nº geral 22782</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Medic. febre alta 2 espécie de serpente cuja picada provoca sede excessiva. 〈καίω〉</p></section></article>\n<article id=\"entry-dgp-22783\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυσόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1998 na letra κ · nº geral 22783</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 queimar ♦ méd. 2 bíbl. ser consumido pelo fogo 3 sentir calor excessivo 4 ter febre ardente. 〈καῦσος〉</p></section></article>\n<article id=\"entry-dgp-22784\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυστείρη, ης</h1><div class=\"entry-meta\"><span>DGP · ordem 1999 na letra κ · nº geral 22784</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) jôn. 1 que queima; abrasador 2 ardente. 〈καυστήρ〉</p></section></article>\n<article id=\"entry-dgp-22785\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυστήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2000 na letra κ · nº geral 22785</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">καυτήρ.</p></section></article>\n<article id=\"entry-dgp-22786\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυστηριάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2001 na letra κ · nº geral 22786</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">καυτηριάζω.</p></section></article>\n<article id=\"entry-dgp-22787\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2002 na letra κ · nº geral 22787</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se pode queimar; combustível 2 Medic. ardente de febre 3 que tem a propriedade de queimar; cáustico 4 por meio do fogo: βάσανοι καυστικοί sept. tortura por meio do fogo. 〈καυστός〉</p></section></article>\n<article id=\"entry-dgp-22788\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καυστός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2003 na letra κ · nº geral 22788</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">combustível.</p></section></article>\n<article id=\"entry-dgp-22789\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καΰστριον πεδίον (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2004 na letra κ · nº geral 22789</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">planície do Caístro.</p></section></article>\n<article id=\"entry-dgp-22790\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καΰστριος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2005 na letra κ · nº geral 22790</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Καΰστρος.</p></section></article>\n";
